import { cn } from "@/lib/utils"

const DETAIL_HOLD_MS = 2000
const CENTER_CROSSFADE = { duration: 0.2, ease: [0.23, 1, 0.32, 1] as const }
const LAYOUT_SPRING = {
  type: "spring" as const,
  duration: 0.34,
  bounce: 0.22,
}

