      size={beamSize}
      staticColors={staticColors}
      strength={strength}
      style={borderBeamStyle}
      theme={theme}
    >
      <InputGroup
        className={cn(
          "min-w-0 self-stretch",
          pill && "h-9 rounded-full has-[textarea]:rounded-md",
          className
        )}
        {...groupProps}
      />
    </BorderBeam>
  )
})

