              "radial-gradient(90% 70% at 50% 100%, rgba(255,0,128,0.28), rgba(121,40,202,0.12) 48%, transparent 62%)",
          }}
        />
        <div
          className="absolute inset-0 opacity-70 blur-xl dark:opacity-50"
          style={{
            background:
              "radial-gradient(70% 55% at 30% 0%, rgba(0,212,255,0.22), rgba(0,112,243,0.08) 45%, transparent 58%)",
          }}
        />
      </div>
    </div>
  )
}

/** Scaled pill blobs for `h-5` badges — same motion keys as `GradientRimPillBlobs`. */
function BadgeRimPillBlobs({
  borderGlow,
  reduceMotion,
}: {
  borderGlow: ReturnType<typeof badgeBorderGlowConfig>
  reduceMotion: boolean
}) {
  return (
    <div className="pointer-events-none absolute inset-0 z-0 overflow-hidden rounded-full">
      <motion.div
        animate={{
          opacity: reduceMotion
            ? borderGlow.opacityIdle * 0.82
            : borderGlow.opacityIdle,
        }}
        className="absolute inset-x-0 bottom-0 h-1/2"
        transition={{ duration: 0.25, ease: "easeOut" }}
      >
        <motion.div
          animate={{
            left: borderGlow.primaryLeft,
          }}
          className="-bottom-2 absolute h-10 w-28 blur-xl"
          style={{
            background: borderGlow.primaryBg,
          }}
          transition={{
            duration: reduceMotion ? 0.01 : borderGlow.durationMain,
            repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
            ease: "easeInOut",
          }}
        />
        <motion.div
          animate={{
            left: borderGlow.secondaryLeft,
          }}
          className="-bottom-1.5 absolute h-8 w-20 blur-lg"
          style={{
            background: borderGlow.secondaryBg,
          }}
          transition={{
            duration: reduceMotion ? 0.01 : borderGlow.durationSec,
            repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
            ease: "easeInOut",
          }}
        />
        <motion.div
          animate={{
            left: borderGlow.tertiaryLeft,
          }}
          className="-bottom-1 absolute h-6 w-16 blur-md"
          style={{
            background: borderGlow.tertiaryBg,
          }}
          transition={{
            duration: reduceMotion ? 0.01 : borderGlow.durationTer,
            repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
            ease: "easeInOut",
          }}
        />
      </motion.div>
    </div>
  )
}

const chromedLabelClasses: Record<
  "default" | "secondary" | "destructive" | "outline",
  string
> = {
  default: "text-primary",
  secondary: "text-muted-foreground",
  destructive:
    "text-destructive aria-invalid:text-destructive dark:aria-invalid:text-destructive",
  outline: "text-foreground",
}

/** Border tints (same `color-mix` system as `HaloSwitch` shell). */
const chromedBorderClasses: Record<
  "default" | "secondary" | "destructive" | "outline",
  string
> = {
  default:
    "border-[color-mix(in_oklch,var(--border)_72%,oklch(0.88_0.06_300))]",
  secondary:
    "border-[color-mix(in_oklch,var(--border)_72%,oklch(0.88_0.06_300))]",
  destructive:
    "border-[color-mix(in_oklch,var(--border)_65%,oklch(0.86_0.09_22))]",
  outline:
    "border-[color-mix(in_oklch,var(--border)_72%,oklch(0.88_0.06_300))]",
}

/** Plain string/number children only — used to pick a perfect circle for single-digit counts. */
function plainChildLength(children: ReactNode): number | null {
  if (typeof children === "string" || typeof children === "number") {
    return String(children).length
  }
  return null
}

/** Explicit transform in transition (never `transition: all`). Easing matches cross-fade polish in the design skill. */
const chromedSurfaceBase =
  "relative z-[1] flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden whitespace-nowrap rounded-full px-2 font-medium text-[0.625rem] leading-none tracking-tight antialiased outline-none transition-[background-color,backdrop-filter,border-color,box-shadow,transform] duration-200 ease-[cubic-bezier(0.2,0,0,1)] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&>svg]:size-2.5"

function chromedShapeClasses(
  singleDigitCircle: boolean,
  multiDigitTabular: boolean
): string {
  if (singleDigitCircle) {
    return "size-5 px-0"
  }
  if (multiDigitTabular) {
    return "h-5 min-w-5 px-1.5"
  }
  return "h-5 px-2"
}

export interface HaloBadgeProps
  extends Omit<ComponentProps<typeof motion.span>, "children">,
    VariantProps<typeof badgeVariants> {
  children?: ReactNode
  /** Leading “live” dot — opacity pulse only (respects reduced motion). */
  live?: boolean
  /**
   * Animate width when label/children change. Prefer off for badges that update very frequently.
   * @default true
   */
  layout?: boolean
  /** Avoids digit shift when children are numeric strings. */
  tabularNums?: boolean
  /** Frosted inner surface so gradient blobs read through (matches other animated components). */
  translucent?: boolean
  /** Stronger rim + fill on hover (matches `HaloCard` / pill buttons). */
  interactive?: boolean
  /**
   * Subtle `scale(0.96)` on press when `interactive` (interruptible CSS transition).
   * @default true
   */
  pressScale?: boolean
}

function HaloBadgeChrome({
  borderGlow,
  body,
  chromedKey,
  className,
  enableLayout,
  fillBackground,
  interactive,
  live,
  onMouseEnter,
  onMouseLeave,
  pressScale,
  pulseTransition,
  reduceMotion,
  singleDigitCircle,
  multiDigitTabular,
  translucent,
  ...props
}: {
  borderGlow: ReturnType<typeof badgeBorderGlowConfig>
  body: ReactNode
  chromedKey: keyof typeof chromedLabelClasses
  className?: string
  enableLayout: boolean
  fillBackground: string
  interactive: boolean
  live: boolean
  onMouseEnter?: ComponentProps<typeof motion.span>["onMouseEnter"]
  onMouseLeave?: ComponentProps<typeof motion.span>["onMouseLeave"]
  pressScale: boolean
  pulseTransition: { duration: number; ease: "easeInOut"; repeat: number }
  reduceMotion: boolean
  singleDigitCircle: boolean
  multiDigitTabular: boolean
  translucent: boolean
} & Omit<ComponentProps<typeof motion.span>, "children">) {
  const shapeClasses = chromedShapeClasses(singleDigitCircle, multiDigitTabular)

  return (
    <motion.span
      className={cn(
        "relative inline-flex max-w-full items-center self-center leading-none",
        className
      )}
      data-slot="halo-badge"
      layout={enableLayout}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      transition={layoutTransition}
      {...props}
    >
      {translucent ? (
        <BadgeAmbientUnderglow reduceMotion={reduceMotion} />
      ) : null}
      {/*
        Inline baseline/line-height on the rim wrapper skews the inner pill inside `p-px`.
        `inline-flex` + `leading-none` + `text-[0]` keeps the ring concentric; text size is set on the inner surface.
      */}
      {/*
        Concentric radii: outer `rounded-full` + `p-px` (1px) with inner `rounded-full`
        reads as a pill ring; both use full rounding so caps stay semicircular.
      */}
      <span className="relative z-[1] inline-flex items-center justify-center rounded-full p-px text-[0] leading-none">
        <BadgeRimPillBlobs
          borderGlow={borderGlow}
          reduceMotion={reduceMotion}
        />
        <span
          className={cn(
            chromedSurfaceBase,
            chromedLabelClasses[chromedKey],
            shapeClasses,
            interactive && "touch-manipulation",
            interactive &&
              pressScale &&
              !reduceMotion &&
              "active:scale-[0.96] motion-reduce:active:scale-100",
            /* Shell border + shadows aligned with `HaloSwitch` outer shell */
            "border",
            chromedBorderClasses[chromedKey],
            "shadow-[0_1px_0_rgba(255,255,255,0.55)_inset,0_1px_2px_rgba(0,0,0,0.03),0_6px_18px_rgba(0,0,0,0.04)]",
            "dark:border-border/80 dark:shadow-[0_1px_0_rgba(255,255,255,0.05)_inset,0_1px_2px_rgba(0,0,0,0.28),0_6px_22px_rgba(0,0,0,0.32)]",
            interactive &&
              "fine-hover:hover:border-ring/50 fine-hover:hover:shadow-[0_1px_0_rgba(255,255,255,0.6)_inset,0_1px_3px_rgba(0,0,0,0.05),0_8px_22px_rgba(0,0,0,0.06)]",
            interactive &&
              "dark:fine-hover:hover:border-zinc-500/60 dark:fine-hover:hover:shadow-[0_1px_0_rgba(255,255,255,0.08)_inset,0_2px_4px_rgba(0,0,0,0.38),0_10px_28px_rgba(0,0,0,0.42)]",
            translucent && "backdrop-blur-xl backdrop-saturate-150"
          )}
          style={{ background: fillBackground }}
        >
          {live ? (
            <motion.span
              animate={
                reduceMotion ? { opacity: 1 } : { opacity: [0.35, 1, 0.35] }
              }
              aria-hidden
              className="size-1.5 shrink-0 translate-y-[0.5px] self-center rounded-full bg-current opacity-90"
              transition={pulseTransition}
            />
          ) : null}
          {body}
        </span>
      </span>
    </motion.span>
  )
}

export function HaloBadge({
  variant = "default",
  className,
  children,
  live = false,
  layout = true,
  tabularNums = false,
  translucent = true,
  interactive = true,
  pressScale = true,
  onMouseEnter,
  onMouseLeave,
  ...props
}: HaloBadgeProps) {
  const reduceMotion = useReducedMotion() ?? false
  const enableLayout = layout && !reduceMotion
  const [isHovered, setIsHovered] = useState(false)

  const pulseTransition = useMemo(
    () => ({
      duration: reduceMotion ? 0 : 1.15,
      ease: "easeInOut" as const,
      repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
    }),
    [reduceMotion]
  )

  const body =
    tabularNums || live ? (
      <span
        className={cn(
          "inline-flex items-center leading-none",
          tabularNums && "font-variant-numeric tabular-nums tracking-tight",
          live && "min-w-[1ch]"
        )}
      >
        {children}
      </span>
    ) : (
      <span className="inline-flex items-center leading-none">{children}</span>
    )

  const resolvedVariant = variant ?? ("default" as NonNullable<typeof variant>)
  const useChrome = CHROMED_BADGE_VARIANTS.has(resolvedVariant)
  const rimVariant = badgeRimVariant(resolvedVariant)
  const rimEmphasis = interactive && isHovered

  const digitLen = plainChildLength(children)
  const singleDigitCircle = Boolean(tabularNums) && digitLen === 1 && !live
  const multiDigitTabular =
    Boolean(tabularNums) && !live && digitLen !== null && digitLen > 1

  const borderGlow = useMemo(
    () => badgeBorderGlowConfig(translucent, rimEmphasis, rimVariant),
    [translucent, rimEmphasis, rimVariant]
  )

  const fillBackground = useMemo(
    () => badgeFillBackgroundFor(translucent, interactive, rimEmphasis),
    [translucent, interactive, rimEmphasis]
  )

  if (!useChrome) {
    return (
      <motion.span
        className={cn(badgeVariants({ variant }), "relative", className)}
        layout={enableLayout}
        transition={layoutTransition}
        {...props}
      >
        {live ? (
          <motion.span
            animate={
              reduceMotion ? { opacity: 1 } : { opacity: [0.35, 1, 0.35] }
            }
            aria-hidden
            className="size-1.5 shrink-0 translate-y-[0.5px] self-center rounded-full bg-current opacity-90"
            transition={pulseTransition}
          />
        ) : null}
        {body}
      </motion.span>
    )
  }

  const chromedKey = resolvedVariant as keyof typeof chromedLabelClasses

  return (
    <HaloBadgeChrome
      body={body}
      borderGlow={borderGlow}
      chromedKey={chromedKey}
      className={className}
      enableLayout={enableLayout}
      fillBackground={fillBackground}
      interactive={interactive}
      live={live}
      multiDigitTabular={multiDigitTabular}
      onMouseEnter={(e) => {
        setIsHovered(true)
        onMouseEnter?.(e)
      }}
      onMouseLeave={(e) => {
        setIsHovered(false)
        onMouseLeave?.(e)
      }}
      pressScale={pressScale}
      pulseTransition={pulseTransition}
      reduceMotion={reduceMotion}
      singleDigitCircle={singleDigitCircle}
      translucent={translucent}
      {...props}
    />
  )
}

"use client"

/**
 * Primary action button matching `HaloSearchInput` polish: animated gradient
 * rim, frosted fill, staggered label, loading text + trailing spinner crossfade.
 */
import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"

const LABEL_STAGGER_SEC = 0.018
const LABEL_CHAR_DURATION_SEC = 0.16
const DEFAULT_LOADING_STAGGER_SEC = 0.038
const DEFAULT_LOADING_CHAR_DURATION_SEC = 0.36
const TRAILING_EXIT_DURATION_SEC = 0.2

/** Layout spring: smooth width when label/spinner changes; bounce kept low per motion skill. */
const layoutSpring = {
  type: "spring" as const,
  bounce: 0.12,
  damping: 34,
  stiffness: 420,
}

const trailingExitTransition = (reduceMotion: boolean) => ({
  duration: reduceMotion ? 0 : TRAILING_EXIT_DURATION_SEC,
  ease: "easeOut" as const,
})

const trailingCrossfade = (reduceMotion: boolean) => ({
  exit: {
    opacity: reduceMotion ? 1 : 0,
    scale: reduceMotion ? 1 : 0.88,
  },
  initial: {
    opacity: reduceMotion ? 1 : 0,
    scale: reduceMotion ? 1 : 0.88,
  },
})

function ButtonSpinner({
  className,
  reduceMotion,
}: {
  className?: string
  reduceMotion: boolean
}) {
  return (
    <span
      className={cn(
        "inline-flex origin-center text-muted-foreground",
        !reduceMotion && "animate-spin",
        className
      )}
    >
      <svg
        aria-hidden="true"
        className="h-3.5 w-3.5"
        focusable="false"
        viewBox="0 0 24 24"
      >
        <circle
          className="opacity-[0.22]"
          cx="12"
          cy="12"
          fill="none"
          r="9"
          stroke="currentColor"
          strokeWidth="2.25"
        />
        <circle
          cx="12"
          cy="12"
          fill="none"
          r="9"
          stroke="currentColor"
          strokeDasharray="14 42"
          strokeLinecap="round"
          strokeWidth="2.25"
        />
      </svg>
    </span>
  )
}

function StaggeredTextLabel({
  text,
  reduceMotion,
  staggerSec = LABEL_STAGGER_SEC,
  charDurationSec = LABEL_CHAR_DURATION_SEC,
}: {
  text: string
  reduceMotion: boolean
  staggerSec?: number
  charDurationSec?: number
}) {
  const chars = useMemo(() => {
    const counts = new Map<string, number>()
    return Array.from(text, (char) => {
      const count = counts.get(char) ?? 0
      counts.set(char, count + 1)
      return { char, key: `${char}-${count}` }
    })
  }, [text])

  return (
    <motion.span
      animate="visible"
      className="inline-flex items-center font-medium text-foreground text-sm tracking-tight antialiased"
      initial="hidden"
      key={text}
      variants={{
        hidden: {},
        visible: {
          transition: {
            staggerChildren: reduceMotion ? 0 : staggerSec,
          },
        },
      }}
    >
      {chars.map((glyph) => (
        <motion.span
          className="inline-block whitespace-pre"
          key={glyph.key}
          transition={{
            duration: reduceMotion ? 0 : charDurationSec,
            ease: "easeOut",
          }}
          variants={{
            hidden: { opacity: reduceMotion ? 1 : 0 },
            visible: { opacity: 1 },
          }}
        >
          {glyph.char}
        </motion.span>
      ))}
    </motion.span>
  )
}

function TrailingLoadingSlot({
  reduceMotion,
  reveal,
}: {
  reduceMotion: boolean
  reveal: boolean
}) {
  const cross = trailingCrossfade(reduceMotion)
  return (
    <motion.div
      animate={
        reveal
          ? { opacity: 1, scale: 1 }
          : { opacity: 0, scale: reduceMotion ? 1 : 0.88 }
      }
      aria-hidden
      className={cn(
        "absolute inset-0 flex items-center justify-center rounded-full",
        "pointer-events-none bg-muted text-muted-foreground shadow-foreground/10 shadow-sm ring-1 ring-foreground/10"
      )}
      exit={{ ...cross.exit, transition: trailingExitTransition(reduceMotion) }}
      initial={cross.initial}
      key="trailing-loading"
      transition={
        reduceMotion
          ? { duration: 0 }
          : reveal
            ? { ...layoutSpring }
            : { duration: 0 }
      }
    >
      <ButtonSpinner reduceMotion={reduceMotion} />
    </motion.div>
  )
}

export interface HaloButtonProps
  extends Omit<ComponentProps<typeof ButtonPrimitive>, "children"> {
  children: ReactNode
  /** Frosted inner surface so gradient blobs read through (matches search translucent mode). */
  translucent?: boolean
  /** Shows trailing spinner and sets `aria-busy`; label switches to `loadingText`. */
  isLoading?: boolean
  /** Copy shown while `isLoading` (staggered when `staggerLabel` is true). */
  loadingText?: string
  /** Stagger between loading glyphs (seconds). */
  loadingStaggerSec?: number
  /** Duration of each loading glyph fade-in (seconds). */
  loadingCharDurationSec?: number
  /**
   * When `children` is a string, replay character stagger on change.
   * Ignored for non-string children.
   */
  staggerLabel?: boolean
  className?: string
}

export function HaloButton({
  children,
  className,
  translucent = true,
  isLoading = false,
  loadingText = "Working…",
  loadingStaggerSec = DEFAULT_LOADING_STAGGER_SEC,
  loadingCharDurationSec = DEFAULT_LOADING_CHAR_DURATION_SEC,
  staggerLabel = true,
  disabled,
  onFocus,
  onBlur,
  onMouseEnter,
  onMouseLeave,
  style,
  ...props
}: HaloButtonProps) {
  const [isFocused, setIsFocused] = useState(false)
  const [isHovered, setIsHovered] = useState(false)
  /** Spinner fades in only after outer `layout` width animation finishes (avoids leading the expansion). */
  const [trailingRevealReady, setTrailingRevealReady] = useState(false)
  const reduceMotion = useReducedMotion() ?? false
  const isLoadingRef = useRef(isLoading)
  isLoadingRef.current = isLoading

  useEffect(() => {
    if (!isLoading) {
      setTrailingRevealReady(false)
      return
    }
    if (reduceMotion) {
      setTrailingRevealReady(true)
    }
  }, [isLoading, reduceMotion])

  /** If layout completion never fires (e.g. zero delta), still reveal the spinner. */
  useEffect(() => {
    if (!isLoading || reduceMotion) {
      return
    }
    const id = window.setTimeout(() => {
      setTrailingRevealReady(true)
    }, 480)
    return () => window.clearTimeout(id)
  }, [isLoading, reduceMotion])

  /** `disabled` + `pointer-events-none` while loading can strand `isHovered`; ignore hover then. */
  const hoverAllowed = !(disabled || isLoading)
  const rimEmphasis = isFocused || (isHovered && hoverAllowed)

  const borderGlow = useMemo(() => {
    let idleOpacity: number
    if (translucent) {
      idleOpacity = rimEmphasis ? 0.92 : 0.72
    } else {
      idleOpacity = rimEmphasis ? 0.78 : 0.5
    }
    return {
      opacityIdle: idleOpacity,
      primaryBg: "linear-gradient(90deg, #ff0080, #7928ca, #00d4ff, #0070f3)",
      secondaryBg: "linear-gradient(90deg, #ff4d4d, #f9cb28, #ff0080)",
      tertiaryBg: "linear-gradient(90deg, #0070f3, #00d4ff, #7928ca)",
      primaryLeft: ["-5%", "75%", "-5%"],
      secondaryLeft: ["65%", "10%", "65%"],
      tertiaryLeft: ["25%", "55%", "25%"],
      durationMain: 6,
      durationSec: 5,
      durationTer: 4,
    }
  }, [translucent, rimEmphasis])

  const labelIsString = typeof children === "string"
  const showTrailing = isLoading

  const labelContent = (() => {
    if (isLoading) {
      if (staggerLabel) {
        return (
          <StaggeredTextLabel
            charDurationSec={loadingCharDurationSec}
            reduceMotion={reduceMotion}
            staggerSec={loadingStaggerSec}
            text={loadingText}
          />
        )
      }
      return (
        <span className="font-medium text-foreground text-sm tracking-tight antialiased">
          {loadingText}
        </span>
      )
    }
    if (labelIsString && staggerLabel) {
      return <StaggeredTextLabel reduceMotion={reduceMotion} text={children} />
    }
    return (
      <span className="font-medium text-foreground text-sm tracking-tight antialiased">
        {children}
      </span>
    )
  })()

  let fillBackground: string
  if (translucent) {
    if (isHovered && hoverAllowed) {
      fillBackground =
        "linear-gradient(to bottom, color-mix(in oklch, var(--card) 88%, transparent) 0%, color-mix(in oklch, var(--card) 74%, transparent) 100%)"
    } else {
      fillBackground =
        "linear-gradient(to bottom, color-mix(in oklch, var(--card) 82%, transparent) 0%, color-mix(in oklch, var(--card) 70%, transparent) 100%)"
    }
  } else if (isHovered && hoverAllowed) {
    fillBackground =
      "linear-gradient(to bottom, var(--card) 0%, color-mix(in oklch, var(--card) 90%, var(--muted)) 100%)"
  } else {
    fillBackground =
      "linear-gradient(to bottom, var(--card) 0%, color-mix(in oklch, var(--card) 94%, var(--muted)) 100%)"
  }

  return (
    <motion.div
      className={cn("relative inline-flex max-w-full", className)}
      layout={!reduceMotion}
      transition={reduceMotion ? undefined : { layout: layoutSpring }}
      onLayoutAnimationComplete={() => {
        if (isLoadingRef.current && !reduceMotion) {
          setTrailingRevealReady(true)
        }
      }}
    >
      <div className="relative rounded-full p-px">
        <div className="pointer-events-none absolute inset-0 overflow-hidden rounded-full">
          <motion.div
            animate={{
              opacity: borderGlow.opacityIdle,
            }}
            className="absolute inset-x-0 bottom-0 h-1/2"
            transition={{ duration: 0.25, ease: "easeOut" }}
          >
            <motion.div
              animate={{
                left: borderGlow.primaryLeft,
              }}
              className="-bottom-4 absolute h-16 w-48 blur-xl"
              style={{
                background: borderGlow.primaryBg,
              }}
              transition={{
                duration: borderGlow.durationMain,
                repeat: Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }}
            />
            <motion.div
              animate={{
                left: borderGlow.secondaryLeft,
              }}
              className="-bottom-3 absolute h-12 w-32 blur-lg"
              style={{
                background: borderGlow.secondaryBg,
              }}
              transition={{
                duration: borderGlow.durationSec,
                repeat: Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }}
            />
            <motion.div
              animate={{
                left: borderGlow.tertiaryLeft,
              }}
              className="-bottom-2 absolute h-10 w-24 blur-lg"
              style={{
                background: borderGlow.tertiaryBg,
              }}
              transition={{
                duration: borderGlow.durationTer,
                repeat: Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }}
            />
          </motion.div>
        </div>

        <ButtonPrimitive
          aria-busy={isLoading || undefined}
          className={cn(
            "relative flex min-h-11 min-w-0 select-none items-center gap-2.5 rounded-full px-6 py-2.5",
            "border border-border/90",
            "shadow-[0_1px_0_rgba(255,255,255,0.1)_inset,0_1px_2px_rgba(0,0,0,0.04),0_4px_14px_rgba(0,0,0,0.05)]",
            "dark:border-border dark:shadow-[0_1px_0_rgba(255,255,255,0.06)_inset,0_1px_2px_rgba(0,0,0,0.35),0_4px_20px_rgba(0,0,0,0.35)]",
            "outline-none focus-visible:border-ring/70 focus-visible:ring-2 focus-visible:ring-ring/30 dark:focus-visible:border-zinc-500/45",
            "transition-[transform,background-color,backdrop-filter,border-color,box-shadow] duration-200 ease-out",
            "fine-hover:hover:border-ring/50 fine-hover:hover:shadow-[0_1px_0_rgba(255,255,255,0.12)_inset,0_2px_6px_rgba(0,0,0,0.06),0_8px_24px_rgba(0,0,0,0.08)]",
            "dark:fine-hover:hover:border-zinc-500/60 dark:fine-hover:hover:shadow-[0_1px_0_rgba(255,255,255,0.08)_inset,0_4px_12px_rgba(0,0,0,0.45),0_12px_32px_rgba(0,0,0,0.45)]",
            "enabled:active:scale-[0.96] motion-reduce:enabled:active:scale-100",
            "disabled:pointer-events-none disabled:opacity-50",
            translucent && "backdrop-blur-xl backdrop-saturate-150"
          )}
          disabled={disabled || isLoading}
          onBlur={(e) => {
            setIsFocused(false)
            onBlur?.(e)
          }}
          onFocus={(e) => {
            setIsFocused(true)
            onFocus?.(e)
          }}
          onMouseEnter={(e) => {
            setIsHovered(true)
            onMouseEnter?.(e)
          }}
          onMouseLeave={(e) => {
            setIsHovered(false)
            onMouseLeave?.(e)
          }}
          style={{
            ...style,
            background: fillBackground,
          }}
          {...props}
        >
          <span className="flex min-w-0 flex-1 items-center justify-center gap-2">
            {labelContent}
          </span>

          {showTrailing ? (
            <div className="relative size-7 shrink-0">
              <AnimatePresence initial={false} mode="popLayout">
                <TrailingLoadingSlot
                  reduceMotion={reduceMotion}
                  reveal={trailingRevealReady}
                />
              </AnimatePresence>
            </div>
          ) : null}
        </ButtonPrimitive>
      </div>
    </motion.div>
  )
}

"use client"

/**
 * Composable card matching `HaloSearchInput` / `HaloButtonPolished`:
 * animated gradient rim, frosted fill, layered shadow, fine-hover polish.
 *
 * @example
 * <HaloCard aria-label="Example">
 *   <HaloCardHeader>
 *     <HaloCardTitle>Title</HaloCardTitle>
 *     <HaloCardDescription>Body copy.</HaloCardDescription>
 *   </HaloCardHeader>
 *   <HaloCardContent>Optional main area.</HaloCardContent>
 *   <HaloCardFooter>
 *     <HaloCardButton variant="secondary">Cancel</HaloCardButton>
 *     <HaloCardButton variant="primary">Continue</HaloCardButton>
 *   </HaloCardFooter>
 * </HaloCard>
 */
import {
  forwardRef,
  useEffect,
  useMemo,
  useState,
  type ComponentProps,
  type HTMLAttributes,
  type ReactNode,
} from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useTransform,
} from "motion/react"

import { cn } from "@/lib/utils"

const paddingClass = {
  none: "",
  sm: "p-4",
  md: "p-6",
  lg: "p-8",
} as const

const BORDER_TRAIL_LOOP_MS = 5250

/** Moving rim highlight along the card edge (mask = border band only). Phase persists when hover/focus stops. */
function HaloCardBorderTrail({ active }: { active: boolean }) {
  const progress = useMotionValue(0)
  const offsetDistance = useTransform(progress, (v: number) => {
    const wrapped = ((v % 100) + 100) % 100
    return `${wrapped}%`
  })

  useEffect(() => {
    if (!active) {
      return
    }
    let rafId = 0
    let last = performance.now()
    const tick = (now: number) => {
      const dt = now - last
      last = now
      const next = progress.get() + (dt / BORDER_TRAIL_LOOP_MS) * 100
      progress.set(((next % 100) + 100) % 100)
      rafId = requestAnimationFrame(tick)
    }
    rafId = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(rafId)
  }, [active, progress])

  const pathCornerRadiusPx = 16
  const trailLengthPx = 184
  const trailThicknessPx = 32

  const trailBox = {
    height: trailThicknessPx,
    offsetPath: `rect(0 auto auto 0 round ${pathCornerRadiusPx}px)`,
    width: trailLengthPx,
  } as const

  /** Feathered ends + same hue family as `borderGlowConfig` so it reads as one rim system. */
  const ambientGradient =
    "linear-gradient(90deg, transparent 0%, rgba(255,0,128,0) 6%, rgba(255,0,128,0.38) 24%, rgba(121,40,202,0.5) 50%, rgba(0,212,255,0.42) 76%, rgba(0,212,255,0) 94%, transparent 100%)"

  const coreGradient =
    "linear-gradient(90deg, transparent 0%, rgba(255,0,128,0.72) 20%, rgba(200,140,255,0.92) 50%, rgba(0,212,255,0.78) 80%, transparent 100%)"

  return (
    <div
      className={cn(
        "pointer-events-none absolute inset-0 rounded-[inherit] border border-transparent [mask-clip:padding-box,border-box] [mask-composite:intersect] [mask-image:linear-gradient(transparent,transparent),linear-gradient(#000,#000)]",
        active ? "visible opacity-100" : "invisible opacity-0"
      )}
    >
      {/* Wide soft bloom — ties into frosted card edge */}
      <motion.div
        className="absolute opacity-95 dark:opacity-[0.98]"
        style={{
          ...trailBox,
          filter: "blur(12px)",
          offsetDistance,
        }}
      >
        <div
          className="size-full rounded-[999px]"
          style={{
            background: ambientGradient,
            boxShadow:
              "0 0 22px rgba(121,40,202,0.28), 0 0 44px rgba(0,212,255,0.18), 0 0 2px rgba(255,255,255,0.12)",
          }}
        />
      </motion.div>
      {/* Brighter core — higher-opacity read without a hard capsule edge */}
      <motion.div
        className="absolute dark:opacity-[0.94]"
        style={{
          ...trailBox,
          filter: "blur(4px)",
          offsetDistance,
        }}
      >
        <div
          className="size-full rounded-[999px]"
          style={{
            background: coreGradient,
            boxShadow:
              "0 0 14px rgba(255,0,128,0.35), 0 0 28px rgba(0,212,255,0.32), inset 0 0 1px rgba(255,255,255,0.22)",
          }}
        />
      </motion.div>
    </div>
  )
}

function borderGlowConfig(translucent: boolean, rimEmphasis: boolean) {
  let idleOpacity: number
  if (translucent) {
    idleOpacity = rimEmphasis ? 0.92 : 0.72
  } else {
    idleOpacity = rimEmphasis ? 0.78 : 0.5
  }
  return {
    opacityIdle: idleOpacity,
    primaryBg: "linear-gradient(90deg, #ff0080, #7928ca, #00d4ff, #0070f3)",
    secondaryBg: "linear-gradient(90deg, #ff4d4d, #f9cb28, #ff0080)",
    tertiaryBg: "linear-gradient(90deg, #0070f3, #00d4ff, #7928ca)",
    primaryLeft: ["-5%", "75%", "-5%"],
    secondaryLeft: ["65%", "10%", "65%"],
    tertiaryLeft: ["25%", "55%", "25%"],
    durationMain: 6,
    durationSec: 5,
    durationTer: 4,
  }
}

type BorderGlowState = ReturnType<typeof borderGlowConfig>

function GradientRimPillBlobs({
  borderGlow,
  reduceMotion,
}: {
  borderGlow: BorderGlowState
  reduceMotion: boolean
}) {
  return (
    <div className="pointer-events-none absolute inset-0 overflow-hidden rounded-full">
      <motion.div
        animate={{
          opacity: reduceMotion
            ? borderGlow.opacityIdle * 0.82
            : borderGlow.opacityIdle,
        }}
        className="absolute inset-x-0 bottom-0 h-1/2"
        transition={{ duration: 0.25, ease: "easeOut" }}
      >
        <motion.div
          animate={{
            left: borderGlow.primaryLeft,
          }}
          className="-bottom-5 absolute h-20 w-56 blur-2xl"
          style={{
            background: borderGlow.primaryBg,
          }}
          transition={{
            duration: reduceMotion ? 0.01 : borderGlow.durationMain,
            repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
            ease: "easeInOut",
          }}
        />
        <motion.div
          animate={{
            left: borderGlow.secondaryLeft,
          }}
          className="-bottom-4 absolute h-16 w-40 blur-xl"
          style={{
            background: borderGlow.secondaryBg,
          }}
          transition={{
            duration: reduceMotion ? 0.01 : borderGlow.durationSec,
            repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
            ease: "easeInOut",
          }}
        />
        <motion.div
          animate={{
            left: borderGlow.tertiaryLeft,
          }}
          className="-bottom-3 absolute h-14 w-32 blur-lg"
          style={{
            background: borderGlow.tertiaryBg,
          }}
          transition={{
            duration: reduceMotion ? 0.01 : borderGlow.durationTer,
            repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
            ease: "easeInOut",
          }}
        />
      </motion.div>
    </div>
  )
}

function fillBackgroundFor(
  translucent: boolean,
  interactive: boolean,
  rimEmphasis: boolean
) {
  if (translucent) {
    if (interactive && rimEmphasis) {
      return "linear-gradient(to bottom, color-mix(in oklch, var(--card) 88%, transparent) 0%, color-mix(in oklch, var(--card) 74%, transparent) 100%)"
    }
    return "linear-gradient(to bottom, color-mix(in oklch, var(--card) 82%, transparent) 0%, color-mix(in oklch, var(--card) 70%, transparent) 100%)"
  }
  if (interactive && rimEmphasis) {
    return "linear-gradient(to bottom, var(--card) 0%, color-mix(in oklch, var(--card) 90%, var(--muted)) 100%)"
  }
  return "linear-gradient(to bottom, var(--card) 0%, color-mix(in oklch, var(--card) 94%, var(--muted)) 100%)"
}

export interface HaloCardProps extends ComponentProps<"div"> {
  children: ReactNode
  /** Frosted inner surface so gradient blobs read through. */
  translucent?: boolean
  /** Hover + rim emphasis on the animated edge. */
  interactive?: boolean
  /** Padding inside the card surface. */
  padding?: keyof typeof paddingClass
}

const HaloCard = forwardRef<HTMLDivElement, HaloCardProps>(function HaloCard(
  {
    children,
    className,
    translucent = true,
    interactive = true,
    padding = "md",
    "aria-label": ariaLabel = "Card",
    onBlur,
    onFocus,
    onMouseEnter,
    onMouseLeave,
    ...props
  },
  ref
) {
  const [isHovered, setIsHovered] = useState(false)
  const [isFocusedWithin, setIsFocusedWithin] = useState(false)
  const reduceMotion = useReducedMotion() ?? false

  const rimEmphasis = interactive && (isHovered || isFocusedWithin)

  const borderGlow = useMemo(
    () => borderGlowConfig(translucent, rimEmphasis),
    [translucent, rimEmphasis]
  )

  const fillBackground = useMemo(
    () => fillBackgroundFor(translucent, interactive, rimEmphasis),
    [translucent, interactive, rimEmphasis]
  )

  const showTrailChrome = interactive && !reduceMotion
  const trailActive = isHovered || isFocusedWithin

  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: hover drives animated rim; focusable controls render in children.
    // biome-ignore lint/a11y/useSemanticElements: not a form group; fieldset would be incorrect for layout chrome.
    <div
      aria-label={ariaLabel}
      className={cn("relative w-full max-w-full", className)}
      data-slot="halo-card"
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node | null)) {
          setIsFocusedWithin(false)
        }
        onBlur?.(e)
      }}
      onFocus={(e) => {
        if (interactive) {
          setIsFocusedWithin(true)
        }
        onFocus?.(e)
      }}
      onMouseEnter={(e) => {
        if (interactive) {
          setIsHovered(true)
        }
        onMouseEnter?.(e)
      }}
      onMouseLeave={(e) => {
        setIsHovered(false)
        onMouseLeave?.(e)
      }}
      ref={ref}
      role="group"
      {...props}
    >
      <div className="relative rounded-2xl p-px">
        <div className="pointer-events-none absolute inset-0 z-0 overflow-hidden rounded-2xl">
          <motion.div
            animate={{
              opacity: reduceMotion
                ? borderGlow.opacityIdle * 0.82
                : borderGlow.opacityIdle,
            }}
            className="absolute inset-x-0 bottom-0 h-[58%]"
            transition={{ duration: 0.25, ease: "easeOut" }}
          >
            <motion.div
              animate={{
                left: borderGlow.primaryLeft,
              }}
              className="-bottom-10 absolute h-32 w-88 blur-2xl"
              style={{
                background: borderGlow.primaryBg,
              }}
              transition={{
                duration: reduceMotion ? 0.01 : borderGlow.durationMain,
                repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }}
            />
            <motion.div
              animate={{
                left: borderGlow.secondaryLeft,
              }}
              className="-bottom-7 absolute h-24 w-52 blur-2xl"
              style={{
                background: borderGlow.secondaryBg,
              }}
              transition={{
                duration: reduceMotion ? 0.01 : borderGlow.durationSec,
                repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }}
            />
            <motion.div
              animate={{
                left: borderGlow.tertiaryLeft,
              }}
              className="-bottom-5 absolute h-20 w-44 blur-xl"
              style={{
                background: borderGlow.tertiaryBg,
              }}
              transition={{
                duration: reduceMotion ? 0.01 : borderGlow.durationTer,
                repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }}
            />
          </motion.div>
        </div>

        <div
          className={cn(
            "relative z-0 flex flex-col gap-6 rounded-[15px] border border-border/90",
            "shadow-[0_1px_0_rgba(255,255,255,0.1)_inset,0_1px_2px_rgba(0,0,0,0.04),0_4px_14px_rgba(0,0,0,0.05)]",
            "dark:border-border dark:shadow-[0_1px_0_rgba(255,255,255,0.06)_inset,0_1px_2px_rgba(0,0,0,0.35),0_4px_20px_rgba(0,0,0,0.35)]",
            "outline-none transition-[background-color,backdrop-filter,border-color,box-shadow] duration-200 ease-out",
            interactive &&
              "fine-hover:hover:border-ring/50 fine-hover:hover:shadow-[0_1px_0_rgba(255,255,255,0.14)_inset,0_1px_2px_rgba(0,0,0,0.09),0_4px_14px_rgba(0,0,0,0.11)]",
            interactive &&
              "dark:fine-hover:hover:border-zinc-500/60 dark:fine-hover:hover:shadow-[0_1px_0_rgba(255,255,255,0.08)_inset,0_1px_2px_rgba(0,0,0,0.42),0_4px_20px_rgba(0,0,0,0.48)]",
            interactive &&
              "focus-within:border-ring/70 focus-within:shadow-[0_1px_0_rgba(255,255,255,0.14)_inset,0_1px_2px_rgba(0,0,0,0.09),0_4px_14px_rgba(0,0,0,0.11)]",
            interactive &&
              "dark:focus-within:border-zinc-500/55 dark:focus-within:shadow-[0_1px_0_rgba(255,255,255,0.08)_inset,0_1px_2px_rgba(0,0,0,0.42),0_4px_20px_rgba(0,0,0,0.48)]",
            translucent && "backdrop-blur-xl backdrop-saturate-150",
            padding !== "none" && paddingClass[padding]
          )}
          data-slot="halo-card-surface"
          style={{ background: fillBackground }}
        >
          {children}
        </div>

        {showTrailChrome ? (
          <div className="pointer-events-none absolute inset-0 z-10 rounded-2xl">
            <HaloCardBorderTrail active={trailActive} />
          </div>
        ) : null}
      </div>
    </div>
  )
})

