        style={{ willChange: reduceMotion ? undefined : "transform" }}
        transition={{
          duration: reduceMotion ? 0.01 : 1.15,
          ease: "easeInOut",
          repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
