/** Overlay placeholder: each character fades in with a short stagger (re-mounted via `animateKey`). */
function AnimatedPlaceholder({
  text,
  animateKey,
  reduceMotion,
  staggerSec = PLACEHOLDER_STAGGER_SEC,
  charDurationSec = PLACEHOLDER_CHAR_DURATION_SEC,
}: {
  text: string
  animateKey: number
  reduceMotion: boolean
  /** Seconds between starting each child’s entrance. */
  staggerSec?: number
  /** Seconds for each glyph’s opacity fade-in. */
  charDurationSec?: number
}) {
  // Keys like `a-0`, `a-1` so duplicate letters animate independently and remount cleanly.
  const chars = useMemo(() => {
    const counts = new Map<string, number>()

    return Array.from(text, (char) => {
      const count = counts.get(char) ?? 0
      counts.set(char, count + 1)
      return { char, key: `${char}-${count}` }
    })
  }, [text])

  return (
    <motion.span
      animate="visible"
      className="pointer-events-none absolute inset-y-0 left-0 flex items-center text-muted-foreground"
      initial="hidden"
      key={animateKey}
      variants={{
        hidden: {},
        visible: {
          transition: {
            staggerChildren: reduceMotion ? 0 : staggerSec,
          },
        },
      }}
    >
      {chars.map((glyph) => (
        <motion.span
          className="inline-block whitespace-pre"
          key={glyph.key}
          transition={{
            duration: reduceMotion ? 0 : charDurationSec,
            ease: "easeOut",
          }}
          variants={{
            hidden: { opacity: reduceMotion ? 1 : 0 },
            visible: { opacity: 1 },
          }}
        >
          {glyph.char}
        </motion.span>
      ))}
    </motion.span>
  )
}

export function HaloSearchInput({
  className,
  value,
  onChange,
  onClear,
  placeholder = "Ask anything or search",
  blobTranslucent = false,
  isLoading = false,
  loadingText = "Searching…",
  loadingStaggerSec = DEFAULT_LOADING_STAGGER_SEC,
  loadingCharDurationSec = DEFAULT_LOADING_CHAR_DURATION_SEC,
  disabled,
  readOnly,
  ...props
}: HaloSearchInputProps) {
  const showBlobTranslucent = blobTranslucent || isLoading
  const [internalValue, setInternalValue] = useState("")
  const [isFocused, setIsFocused] = useState(false)
  // While true, real input text is hidden and `DeletedTextBlurReveal` shows the last string.
  const [isDeleting, setIsDeleting] = useState(false)
  const [deletionGhostText, setDeletionGhostText] = useState<string | null>(
    null
  )
  // Which code units animate (here: entire string); could be a subset for partial effects.
  const [deletionIndexes, setDeletionIndexes] = useState<number[]>([])
  const [deletionKey, setDeletionKey] = useState(0)
  // Bumps `AnimatedPlaceholder`’s React key so the stagger runs again after a clear.
  const [placeholderAnimKey, setPlaceholderAnimKey] = useState(0)
  const [loadingAnimKey, setLoadingAnimKey] = useState(0)
  const inputRef = useRef<HTMLInputElement>(null)
  const deletionTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const typingIdleTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const [isTypingBurst, setIsTypingBurst] = useState(false)
  const wasDeletingRef = useRef(false)
  const wasLoadingRef = useRef(false)
  const reduceMotion = useReducedMotion() ?? false
  const deleteClipDurationMs = 340
  const deleteSweepDurationMs = deleteClipDurationMs + deleteClipDurationMs / 2

  // Controlled when `value` is passed; otherwise internal state mirrors the input.
  const currentValue = value === undefined ? internalValue : value
  const hasValue = String(currentValue).length > 0

  useEffect(() => {
    return () => {
      if (deletionTimerRef.current) {
        clearTimeout(deletionTimerRef.current)
      }
      if (typingIdleTimerRef.current) {
        clearTimeout(typingIdleTimerRef.current)
      }
    }
  }, [])

  // After deletion teardown, replay placeholder entrance once the field is empty again.
  useEffect(() => {
    if (wasDeletingRef.current && !isDeleting && !hasValue) {
      setPlaceholderAnimKey((k) => k + 1)
    }
    wasDeletingRef.current = isDeleting
  }, [hasValue, isDeleting])

  // Replay loading line stagger each time loading starts (same timing as placeholder).
  useEffect(() => {
    if (isLoading && !wasLoadingRef.current) {
      setLoadingAnimKey((k) => k + 1)
    }
    wasLoadingRef.current = isLoading
  }, [isLoading])

  // Tear down overlay only after glyph timings finish (matches `DeletedTextBlurReveal` stagger).
  const scheduleDeletionEnd = useCallback(
    (deletedCount: number) => {
      if (deletionTimerRef.current) {
        clearTimeout(deletionTimerRef.current)
      }

      const { glyphDurationSec, staggerSpanSec } = getDeletionGlyphTiming({
        sweepDurationMs: deleteSweepDurationMs,
        animatedCount: deletedCount,
        staggerGlyphCount: deletedCount,
      })
      const totalGlyphRunMs = (staggerSpanSec + glyphDurationSec) * 1000
      const teardownDelayMs =
        Math.max(deleteSweepDurationMs, totalGlyphRunMs) + 160

      deletionTimerRef.current = setTimeout(() => {
        setIsDeleting(false)
        setDeletionGhostText(null)
        setDeletionIndexes([])
        deletionTimerRef.current = null
      }, teardownDelayMs)
    },
    [deleteSweepDurationMs]
  )

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    const prevValue = String(currentValue)
    const newLength = e.target.value.length
    const prevLen = prevValue.length

    // Full clear (e.g. select-all + delete): play exit animation, then restore empty field.
    if (newLength === 0 && prevLen > 0 && !reduceMotion) {
      const fullDeletionIndexes = Array.from(
        { length: prevLen },
        (_, idx) => idx
      )
      setDeletionIndexes(fullDeletionIndexes)
      setDeletionGhostText(prevValue)
      setDeletionKey((k) => k + 1)
      setIsDeleting(true)
      scheduleDeletionEnd(prevLen)
    }

    if (onChange) {
      onChange(e)
    } else {
      setInternalValue(e.target.value)
    }

    const isAnimatedFullClear = newLength === 0 && prevLen > 0 && !reduceMotion
    if (!(reduceMotion || isAnimatedFullClear)) {
      if (typingIdleTimerRef.current) {
        clearTimeout(typingIdleTimerRef.current)
      }
      setIsTypingBurst(true)
      typingIdleTimerRef.current = setTimeout(() => {
        setIsTypingBurst(false)
        typingIdleTimerRef.current = null
      }, 420)
    }
  }

  // Mirrors the “clear to empty” path in `handleChange`, then focuses the input.
  const handleClear = () => {
    if (typingIdleTimerRef.current) {
      clearTimeout(typingIdleTimerRef.current)
      typingIdleTimerRef.current = null
    }
    setIsTypingBurst(false)
    if (hasValue && !reduceMotion) {
      const fullDeletionIndexes = Array.from(
        { length: String(currentValue).length },
        (_, idx) => idx
      )
      setDeletionIndexes(fullDeletionIndexes)
      setDeletionGhostText(String(currentValue))
      setDeletionKey((k) => k + 1)
      setIsDeleting(true)
      scheduleDeletionEnd(String(currentValue).length)
    }

    if (onClear) {
      onClear()
    } else {
      setInternalValue("")
    }
    inputRef.current?.focus()
  }

  // Border glow: warmer, faster sweep while text deletion plays (ease-out aligned with exit).
  const borderGlow = useMemo(() => {
    if (isDeleting) {
      return {
        opacityIdle: 0.88,
        primaryBg:
          "linear-gradient(90deg, #fb7185, #f43f5e, #f97316, #ec4899, #a855f7)",
        secondaryBg:
          "linear-gradient(90deg, #fda4af, #fb923c, #f472b6, #fb7185)",
        tertiaryBg:
          "linear-gradient(90deg, #e11d48, #db2777, #c026d3, #9333ea)",
        primaryLeft: ["-8%", "92%", "-8%"],
        secondaryLeft: ["72%", "-2%", "72%"],
        tertiaryLeft: ["35%", "62%", "35%"],
        durationMain: 2.35,
        durationSec: 2,
        durationTer: 1.65,
      }
    }
    let idleOpacity: number
    if (showBlobTranslucent) {
      idleOpacity = isFocused ? 0.92 : 0.72
    } else {
      idleOpacity = isFocused ? 0.78 : 0.5
    }
    return {
      opacityIdle: idleOpacity,
      primaryBg: "linear-gradient(90deg, #ff0080, #7928ca, #00d4ff, #0070f3)",
      secondaryBg: "linear-gradient(90deg, #ff4d4d, #f9cb28, #ff0080)",
      tertiaryBg: "linear-gradient(90deg, #0070f3, #00d4ff, #7928ca)",
      primaryLeft: ["-5%", "75%", "-5%"],
      secondaryLeft: ["65%", "10%", "65%"],
      tertiaryLeft: ["25%", "55%", "25%"],
      durationMain: 6,
      durationSec: 5,
      durationTer: 4,
    }
  }, [showBlobTranslucent, isDeleting, isFocused])

  // Avatar: faster pulse + shader while loading (“thinking”) vs typing burst vs idle.
  const { avatarPulseSec, avatarWarpSpeed } = useMemo(() => {
    if (isLoading) {
      return { avatarPulseSec: 1.65, avatarWarpSpeed: 3.45 }
    }
    if (isTypingBurst) {
      return { avatarPulseSec: 2.65, avatarWarpSpeed: 2.65 }
    }
    return { avatarPulseSec: 5.2, avatarWarpSpeed: 1.15 }
  }, [isLoading, isTypingBurst])

  return (
    <div className={cn("relative w-full max-w-2xl", className)}>
      {/* Outer container for gradient border effect */}
      <div className="relative rounded-full p-px">
        {/* Animated gradient glow layer - sits behind the input */}
        <div className="pointer-events-none absolute inset-0 overflow-hidden rounded-full">
          {/* Gradient container positioned at the bottom */}
          <motion.div
            animate={{
              opacity: borderGlow.opacityIdle,
            }}
            className="absolute inset-x-0 bottom-0 h-1/2"
            transition={{ duration: 0.25, ease: "easeOut" }}
          >
            {/* Main flowing gradient blob */}
            <motion.div
              animate={{
                left: borderGlow.primaryLeft,
              }}
              className="-bottom-4 absolute h-16 w-48 blur-xl"
              key={`g-primary-${isDeleting ? "del" : "idle"}`}
              style={{
                background: borderGlow.primaryBg,
              }}
              transition={{
                duration: borderGlow.durationMain,
                repeat: Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }}
            />
            {/* Secondary warm accent */}
            <motion.div
              animate={{
                left: borderGlow.secondaryLeft,
              }}
              className="-bottom-3 absolute h-12 w-32 blur-lg"
              key={`g-secondary-${isDeleting ? "del" : "idle"}`}
              style={{
                background: borderGlow.secondaryBg,
              }}
              transition={{
                duration: borderGlow.durationSec,
                repeat: Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }}
            />
            {/* Tertiary cool accent */}
            <motion.div
              animate={{
                left: borderGlow.tertiaryLeft,
              }}
              className="-bottom-2 absolute h-10 w-24 blur-lg"
              key={`g-tertiary-${isDeleting ? "del" : "idle"}`}
              style={{
                background: borderGlow.tertiaryBg,
              }}
              transition={{
                duration: borderGlow.durationTer,
                repeat: Number.POSITIVE_INFINITY,
                ease: "easeInOut",
              }}
            />
          </motion.div>
        </div>

        {/* Input container — solid or frosted glass so gradient blobs read through */}
        <div
          aria-busy={isLoading || undefined}
          className={cn(
            "relative flex items-center gap-3 rounded-full px-4 py-3",
            "border border-border",
            "shadow-black/5 shadow-sm dark:shadow-black/30",
            "transition-[background,backdrop-filter,border-color,box-shadow] duration-200",
            isFocused && "border-ring/70 dark:border-zinc-500/45",
            showBlobTranslucent && "backdrop-blur-xl backdrop-saturate-150"
          )}
          style={{
            background: showBlobTranslucent
              ? "linear-gradient(to bottom, color-mix(in oklch, var(--card) 82%, transparent) 0%, color-mix(in oklch, var(--card) 70%, transparent) 100%)"
              : "linear-gradient(to bottom, var(--card) 0%, color-mix(in oklch, var(--card) 94%, var(--muted)) 100%)",
          }}
        >
          <AiBlobWarpAvatar
            pulseDurationSec={avatarPulseSec}
            warpProps={{ speed: avatarWarpSpeed }}
          />

          {/* Input + animated placeholder overlay; empty `placeholder` — label text is custom. */}
          <div className="relative flex-1">
            <input
              {...props}
              className={cn(
                "w-full bg-transparent text-base text-foreground outline-none",
                "caret-foreground",
                "placeholder:text-muted-foreground",
                (isDeleting || isLoading) &&
                  "text-transparent caret-transparent"
              )}
              disabled={disabled}
              onBlur={() => setIsFocused(false)}
              onChange={handleChange}
              onFocus={() => setIsFocused(true)}
              placeholder=""
              readOnly={readOnly || isLoading}
              ref={inputRef}
              type="text"
              value={currentValue}
            />
            {isLoading && (
              <AnimatedPlaceholder
                animateKey={loadingAnimKey}
                charDurationSec={loadingCharDurationSec}
                reduceMotion={reduceMotion}
                staggerSec={loadingStaggerSec}
                text={loadingText}
              />
            )}
            {!(hasValue || isDeleting || isLoading) && (
              <AnimatedPlaceholder
                animateKey={placeholderAnimKey}
                reduceMotion={reduceMotion}
                text={placeholder}
              />
            )}
            {/* Deletion animation - blur reveal sweep over deleted text */}
            <AnimatePresence>
              {isDeleting && deletionGhostText !== null && (
                <DeletedTextBlurReveal
                  animatedIndexes={deletionIndexes}
                  clipDurationMs={deleteClipDurationMs}
                  key={deletionKey}
                  reduceMotion={reduceMotion}
                  showSweep={false}
                  text={deletionGhostText}
                  textClassName="text-foreground"
                />
              )}
            </AnimatePresence>
          </div>

          <SearchTrailingAction
            hasValue={hasValue}
            isLoading={isLoading}
            onClear={handleClear}
            reduceMotion={reduceMotion}
          />
        </div>
      </div>
    </div>
  )
}

interface DeletedTextBlurRevealProps {
  text: string
  animatedIndexes?: number[]
  reduceMotion?: boolean
  className?: string
  textClassName?: string
  clipDurationMs?: number
  blurPx?: number
  saturatePercent?: number
  /** Optional diagonal blur “wiper” (disabled in the search field for a simpler exit). */
  showSweep?: boolean
}

/**
 * Absolute overlay: clones the string as per-glyph spans, blurs/fades them on a delay
 * (right-to-left), optionally with a masked backdrop-blur sweep and soft-light noise strip.
 */
export function DeletedTextBlurReveal({
  text,
  animatedIndexes,
  reduceMotion = false,
  className,
  textClassName,
  clipDurationMs = 340,
  blurPx = 10,
  saturatePercent = 220,
  showSweep = true,
}: DeletedTextBlurRevealProps) {
  const noiseFilterId = useId()
  const sweepDurationMs = clipDurationMs + clipDurationMs / 2
  // Per character + stable key; `order` is index for stagger math.
  const glyphs = useMemo(() => {
    const counts = new Map<string, number>()
    let order = 0

    return Array.from(text, (char) => {
      const count = counts.get(char) ?? 0
      counts.set(char, count + 1)

      const glyph = {
        char,
        key: `${char}-${count}`,
        order,
        index: order,
      }

      order += 1
      return glyph
    })
  }, [text])
  // `null` set means animate every glyph; otherwise only indices in the set animate to blurred state.
  const animatedIndexSet = useMemo(() => {
    if (!animatedIndexes || animatedIndexes.length === 0) {
      return null
    }
    return new Set(animatedIndexes)
  }, [animatedIndexes])
  const animatedCount =
    animatedIndexes && animatedIndexes.length > 0
      ? animatedIndexes.length
      : glyphs.length
  const { glyphDurationSec, glyphDelayStepSec } = getDeletionGlyphTiming({
    sweepDurationMs,
    animatedCount,
    staggerGlyphCount: glyphs.length,
  })

  return (
    <motion.div
      aria-hidden
      className={cn("pointer-events-none absolute inset-0 isolate", className)}
      exit={{
        opacity: 0,
        transition: {
          duration: reduceMotion ? 0 : 0.12,
          delay: reduceMotion ? 0 : 0.22,
          ease: "easeOut",
        },
      }}
      initial={{
        opacity: 1,
      }}
      style={{
        borderRadius: 4,
        overflow: "hidden",
      }}
    >
      <div className="absolute inset-y-0 left-0 flex w-fit max-w-full overflow-hidden">
        <motion.div
          animate={{ clipPath: "inset(0 0 0 0 round 9999px)" }}
          className="relative h-full w-fit max-w-full overflow-hidden"
          initial={{ clipPath: "inset(0 0 0 0 round 9999px)" }}
          transition={{
            duration: 0,
            ease: "easeOut",
          }}
        >
          <span
            className={cn(
              "relative z-10 block min-w-0 select-none text-base text-current",
              textClassName
            )}
            style={{
              height: "100%",
              display: "flex",
              alignItems: "center",
              whiteSpace: "pre",
            }}
          >
            {glyphs.map((glyph) => (
              <motion.span
                animate={
                  animatedIndexSet === null || animatedIndexSet.has(glyph.index)
                    ? {
                        opacity: 0.04,
                        filter: "blur(10px)",
                        y: -1,
                      }
                    : {
                        opacity: 1,
                        filter: "blur(0px)",
                        y: 0,
                      }
                }
                className="inline-block"
                initial={{
                  opacity: 1,
                  filter: "blur(0px)",
                  y: 0,
                }}
                key={glyph.key}
                transition={{
                  duration:
                    reduceMotion ||
                    (animatedIndexSet && !animatedIndexSet.has(glyph.index))
                      ? 0
                      : glyphDurationSec,
                  ease: "easeOut",
                  // End of string animates first (higher `order` → smaller delay expression).
                  delay: reduceMotion
                    ? 0
                    : (glyphs.length - 1 - glyph.order) * glyphDelayStepSec,
                }}
              >
                {glyph.char === " " ? "\u00A0" : glyph.char}
              </motion.span>
            ))}
          </span>

          {/* Moving soft mask + backdrop blur; gradient mask feathers the strip edges. */}
          {showSweep && (
            <div className="pointer-events-none absolute inset-0 overflow-hidden">
              <motion.div
                animate={{ x: "-125%" }}
                className="-right-8 absolute inset-y-0 w-24"
                initial={{ x: "125%" }}
                style={{
                  backdropFilter: `blur(${blurPx}px) saturate(${saturatePercent}%)`,
                  WebkitBackdropFilter: `blur(${blurPx}px) saturate(${saturatePercent}%)`,
                  maskImage:
                    "linear-gradient(to right, rgb(0 0 0 / 1) 70%, transparent)",
                  WebkitMaskImage:
                    "linear-gradient(to right, rgb(0 0 0 / 1) 70%, transparent)",
                }}
                transition={{
                  duration: reduceMotion ? 0 : sweepDurationMs / 1000,
                  ease: "easeOut",
                }}
              />

              {/* Fractal noise rect adds grain along the sweep (soft-light blend). */}
              <motion.svg
                animate={{ x: "-125%", opacity: 0 }}
                aria-hidden="true"
                className="-right-8 absolute inset-y-0 h-full w-24 mix-blend-soft-light"
                focusable="false"
                initial={{ x: "125%", opacity: 0.08 }}
                style={{
                  maskImage:
                    "linear-gradient(to right, rgb(0 0 0 / 1) 72%, transparent)",
                  WebkitMaskImage:
                    "linear-gradient(to right, rgb(0 0 0 / 1) 72%, transparent)",
                }}
                transition={{
                  duration: reduceMotion ? 0 : sweepDurationMs / 1000,
                  ease: "easeOut",
                }}
              >
                <filter id={noiseFilterId}>
                  <feTurbulence
                    baseFrequency="0.85"
                    numOctaves="2"
                    stitchTiles="stitch"
                    type="fractalNoise"
                  />
                  <feColorMatrix type="saturate" values="0" />
                </filter>
                <rect
                  filter={`url(#${noiseFilterId})`}
                  height="100%"
                  width="100%"
                />
              </motion.svg>
            </div>
          )}
        </motion.div>
      </div>
    </motion.div>
  )
}

const DEFAULT_WARP: Partial<WarpProps> = {
  /** Matches idle `borderGlow` blobs: primary, secondary, tertiary gradient leading stops. */
  // colors: ["#ff0080", "#ff4d4d", "#0070f3", "#00d4ff", "#7928ca"],
  // colors: ["#ff0080", "#7928ca", "#00d4ff", "#0070f3"],
  colors: ["#fda4af", "#0070f3", "#fb923c", "#f472b6", "#00d4ff"],
  distortion: 0.25,
  height: 720,
  proportion: 0.54,
  scale: 0.2,
  shape: "checks",
  shapeScale: 1,
  softness: 1,
  speed: 0.1,
  swirl: 0.8,
  swirlIterations: 10,
  width: 1280,
}

export type AiBlobWarpAvatarProps = Omit<ComponentProps<"div">, "children"> & {
  /** Scale / rotate loop length in seconds. Default 5.2. */
  pulseDurationSec?: number
  /** Props forwarded to the Paper `Warp` shader (merged after defaults). */
  warpProps?: Partial<WarpProps>
}

/**
 * Circular avatar frame with an animated Warp shader inside.
 * Motion uses transforms only; shader speed pauses off-screen and when `prefers-reduced-motion` is set.
 */
export const AiBlobWarpAvatar = forwardRef<
  HTMLDivElement,
  AiBlobWarpAvatarProps
>(function AiBlobWarpAvatarImpl(
  { className, pulseDurationSec = 5.2, warpProps, ...props },
  forwardedRef
) {
  const {
    className: warpClassName,
    speed: warpSpeed,
    ...restWarpProps
  } = warpProps ?? {}
  const rootRef = useRef<HTMLDivElement>(null)
  const reduceMotion = useReducedMotion()
  const inView = useInView(rootRef, {
    amount: 0.2,
    margin: "0px 0px -10% 0px",
  })
  const live = inView && !reduceMotion

  const setRefs = useCallback(
    (node: HTMLDivElement | null) => {
      rootRef.current = node
      if (typeof forwardedRef === "function") {
        forwardedRef(node)
      } else if (forwardedRef) {
        forwardedRef.current = node
      }
    },
    [forwardedRef]
  )

  const baseSpeed = warpSpeed ?? DEFAULT_WARP.speed ?? 1

  return (
    <div
      className={cn(
        "relative isolate size-8 overflow-hidden rounded-full bg-muted shadow-foreground/10 shadow-sm ring-1 ring-foreground/10",
        className
      )}
      ref={setRefs}
      {...props}
    >
      <motion.div
        animate={
          live
            ? {
                scale: [1, 1.055, 0.99, 1],
                rotate: [0, 2, -1.5, 0],
              }
            : { scale: 1, rotate: 0 }
        }
        aria-hidden
        className="pointer-events-none absolute inset-0 origin-center rounded-full"
        transition={{
          duration: pulseDurationSec,
          ease: "easeInOut",
          repeat: Number.POSITIVE_INFINITY,
        }}
      >
        <Warp
          {...DEFAULT_WARP}
          {...restWarpProps}
          speed={live ? baseSpeed : 0}
        />
      </motion.div>
    </div>
  )
})

"use client"

/**
 * Segmented control (single-select toggle group) aligned with `HaloButtonPolished`:
 * frosted track, gradient rim, sliding thumb using the same layout spring as the button.
 */
import {
  useCallback,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react"
import { Toggle } from "@base-ui/react/toggle"
import { ToggleGroup } from "@base-ui/react/toggle-group"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"

/** Matches `layoutSpring` in `halo-button-polished.tsx`. */
const layoutSpring = {
  type: "spring" as const,
  bounce: 0.12,
  damping: 34,
  stiffness: 420,
}

export interface HaloSegmentedItem {
  value: string
  label: ReactNode
  disabled?: boolean
}

export interface HaloSegmentedProps {
  items: HaloSegmentedItem[]
  /** Selected value; omit for uncontrolled usage with `defaultValue`. */
  value?: string
  defaultValue?: string
  onValueChange?: (next: string) => void
  className?: string
  /** Frosted track + backdrop blur (matches card/button translucent mode). */
  translucent?: boolean
  disabled?: boolean
}

export function HaloSegmented({
  items,
  value: valueProp,
  defaultValue,
  onValueChange,
  className,
  translucent = true,
  disabled = false,
}: HaloSegmentedProps) {
  const reduceMotion = useReducedMotion() ?? false
  const trackRef = useRef<HTMLDivElement>(null)
  const itemRefs = useRef<Map<string, HTMLButtonElement>>(new Map())
  const [thumb, setThumb] = useState({ x: 0, width: 0 })

  const isControlled = valueProp !== undefined
  const [uncontrolled, setUncontrolled] = useState(
    defaultValue ?? items[0]?.value ?? ""
  )
  const selected = isControlled ? (valueProp ?? "") : uncontrolled

  const setSelected = useCallback(
    (next: string) => {
      if (!isControlled) {
        setUncontrolled(next)
      }
      onValueChange?.(next)
    },
    [isControlled, onValueChange]
  )

  const groupValue = useMemo(() => (selected ? [selected] : []), [selected])

  const measureThumb = useCallback(() => {
    const track = trackRef.current
    const active = selected ? itemRefs.current.get(selected) : undefined
    if (!(track && active)) {
      setThumb({ x: 0, width: 0 })
      return
    }
    const tr = track.getBoundingClientRect()
    const br = active.getBoundingClientRect()
    setThumb({
      x: br.left - tr.left,
      width: br.width,
    })
  }, [selected])

  useLayoutEffect(() => {
    measureThumb()
  }, [measureThumb])

  useLayoutEffect(() => {
    const track = trackRef.current
    if (!track || typeof ResizeObserver === "undefined") {
      return
    }
    const ro = new ResizeObserver(() => measureThumb())
    ro.observe(track)
    return () => ro.disconnect()
  }, [measureThumb])

  return (
    <div
      className={cn(
        "relative inline-flex max-w-full rounded-full p-px",
        className
      )}
    >
      <div className="pointer-events-none absolute inset-0 overflow-hidden rounded-full">
        <motion.div
          animate={{
            opacity: translucent ? 0.72 : 0.5,
          }}
          className="absolute inset-x-0 bottom-0 h-1/2"
          transition={{ duration: 0.25, ease: "easeOut" }}
        >
          <motion.div
            animate={{ left: ["-5%", "75%", "-5%"] }}
            className="-bottom-4 absolute h-14 w-44 blur-xl"
            style={{
              background:
                "linear-gradient(90deg, #ff0080, #7928ca, #00d4ff, #0070f3)",
            }}
            transition={{
              duration: reduceMotion ? 0.01 : 6,
              ease: "easeInOut",
              repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
            }}
          />
          <motion.div
            animate={{ left: ["65%", "10%", "65%"] }}
            className="-bottom-3 absolute h-11 w-36 blur-lg"
            style={{
              background: "linear-gradient(90deg, #ff4d4d, #f9cb28, #ff0080)",
            }}
            transition={{
              duration: reduceMotion ? 0.01 : 5,
              ease: "easeInOut",
              repeat: reduceMotion ? 0 : Number.POSITIVE_INFINITY,
            }}
          />
        </motion.div>
      </div>

      <div
        className={cn(
          "relative rounded-full border border-border/90",
          "shadow-[0_1px_0_rgba(255,255,255,0.1)_inset,0_1px_2px_rgba(0,0,0,0.04),0_4px_14px_rgba(0,0,0,0.05)]",
          "dark:border-border dark:shadow-[0_1px_0_rgba(255,255,255,0.06)_inset,0_1px_2px_rgba(0,0,0,0.35),0_4px_20px_rgba(0,0,0,0.35)]",
          translucent && "backdrop-blur-xl backdrop-saturate-150"
        )}
        style={{
          background: translucent
            ? "linear-gradient(to bottom, color-mix(in oklch, var(--card) 82%, transparent) 0%, color-mix(in oklch, var(--card) 70%, transparent) 100%)"
            : "linear-gradient(to bottom, var(--card) 0%, color-mix(in oklch, var(--card) 94%, var(--muted)) 100%)",
        }}
      >
        <div className="relative p-1" ref={trackRef}>
          <motion.div
            animate={{
              x: thumb.width > 0 ? thumb.x : 0,
              width: thumb.width,
            }}
            aria-hidden
            className={cn(
              "pointer-events-none absolute top-1 right-auto bottom-1 left-0 rounded-full",
              "border border-border/70",
              "bg-gradient-to-b from-background/95 to-muted/40",
              "shadow-[0_1px_0_rgba(255,255,255,0.12)_inset,0_2px_8px_rgba(0,0,0,0.06)]",
              "dark:border-white/10 dark:from-card/95 dark:to-muted/25",
              "dark:shadow-[0_1px_0_rgba(255,255,255,0.06)_inset,0_4px_12px_rgba(0,0,0,0.35)]"
            )}
            initial={false}
            transition={reduceMotion ? { duration: 0 } : layoutSpring}
          />

          <ToggleGroup
            className="relative z-1 flex min-w-0 gap-0"
            disabled={disabled}
            multiple={false}
            onValueChange={(next) => {
              const first = next[0]
              if (typeof first === "string") {
                setSelected(first)
              }
            }}
            value={groupValue}
          >
            {items.map((item) => (
              <Toggle
                className={cn(
                  "relative flex min-h-9 min-w-0 flex-1 items-center justify-center rounded-full px-4 py-2",
                  "font-medium text-muted-foreground text-sm tracking-tight antialiased",
                  "outline-none transition-colors duration-200 ease-out",
                  "focus-visible:ring-2 focus-visible:ring-ring/35 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                  "disabled:pointer-events-none disabled:opacity-50",
                  "aria-pressed:text-foreground"
                )}
                disabled={item.disabled}
                key={item.value}
                ref={(el) => {
                  if (el) {
                    itemRefs.current.set(item.value, el)
                  } else {
                    itemRefs.current.delete(item.value)
                  }
                }}
                value={item.value}
              >
                {item.label}
              </Toggle>
            ))}
          </ToggleGroup>
        </div>
      </div>
    </div>
  )
}

"use client"

/**
 * Composable animated select (gradient rim, frosted fill, staggered label, trailing
 * chevron / check / spinner). API mirrors `components/ui/select.tsx`: `HaloSelect`
 * (root), `HaloSelectTrigger`, `HaloSelectValue`, `HaloSelectContent`,
 * `HaloSelectItem`, plus group/label/scroll/separator aliases.
 */
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react"
import {
  Select as SelectPrimitive,
  type SelectRoot,
} from "@base-ui/react/select"
import { Check, ChevronDown } from "lucide-react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import {
  Select,
  SelectGroup,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectContent as UiSelectContent,
} from "@/registry/default/ui/base-select"

const LABEL_STAGGER_SEC = 0.018
const LABEL_CHAR_DURATION_SEC = 0.16
const TRAILING_ACTION_DURATION_SEC = 0.2
const LIST_STAGGER_STEP_SEC = 0.055
const LIST_STAGGER_CAP = 9
const SELECTION_FLASH_MS = 560

interface BorderGlowConfig {
  opacityIdle: number
  primaryBg: string
  secondaryBg: string
  tertiaryBg: string
  primaryLeft: string[]
  secondaryLeft: string[]
  tertiaryLeft: string[]
  durationMain: number
  durationSec: number
  durationTer: number
}

export interface PolishedSelectItem {
  value: string
  label: string
  disabled?: boolean
}

type SelectValueChangeDetails = Parameters<
  NonNullable<SelectRoot.Props<PolishedSelectItem>["onValueChange"]>
>[1]

interface HaloSelectContextValue {
  translucent: boolean
  isLoading: boolean
  showSelectionFlash: boolean
  reduceMotion: boolean
  open: boolean
  setOpen: (open: boolean) => void
  isFocused: boolean
  setIsFocused: (focused: boolean) => void
  listBurst: number
  labelStagger: { key: number; text: string }
  showStaggerOverlay: boolean
  placeholder: string
  borderGlow: BorderGlowConfig
  trailingMode: "spinner" | "check" | "chevron"
  fieldId: string
}

const HaloSelectContext = createContext<HaloSelectContextValue | null>(null)

function useHaloSelect() {
  const ctx = useContext(HaloSelectContext)
  if (!ctx) {
    throw new Error(
      "Animated select components must be used within <HaloSelect>."
    )
  }
  return ctx
}

function SelectStaggeredGlyphLine({
  text,
  animateKey,
  reduceMotion,
  className,
}: {
  text: string
  animateKey: number
  reduceMotion: boolean
  className?: string
}) {
  const chars = useMemo(() => {
    const counts = new Map<string, number>()
    return Array.from(text, (char) => {
      const count = counts.get(char) ?? 0
      counts.set(char, count + 1)
      return { char, key: `${char}-${count}` }
    })
  }, [text])

  return (
    <motion.span
      animate="visible"
      className={className}
      initial="hidden"
      key={animateKey}
      variants={{
        hidden: {},
        visible: {
          transition: {
            staggerChildren: reduceMotion ? 0 : LABEL_STAGGER_SEC,
          },
        },
      }}
    >
      {chars.map((glyph) => (
        <motion.span
          className="inline-block whitespace-pre"
          key={glyph.key}
          transition={{
            duration: reduceMotion ? 0 : LABEL_CHAR_DURATION_SEC,
            ease: "easeOut",
          }}
          variants={{
            hidden: { opacity: reduceMotion ? 1 : 0 },
            visible: { opacity: 1 },
          }}
        >
          {glyph.char}
        </motion.span>
      ))}
    </motion.span>
  )
}

function TrailingSpinner({
  className,
  reduceMotion,
}: {
  className?: string
  reduceMotion: boolean
}) {
  return (
    <span
      className={cn(
        "inline-flex origin-center text-muted-foreground",
        !reduceMotion && "animate-spin",
        className
      )}
    >
      <svg
        aria-hidden="true"
        className="h-3.5 w-3.5"
        focusable="false"
        viewBox="0 0 24 24"
      >
        <circle
          className="opacity-[0.22]"
          cx="12"
          cy="12"
          fill="none"
          r="9"
          stroke="currentColor"
          strokeWidth="2.25"
        />
        <circle
          cx="12"
          cy="12"
          fill="none"
          r="9"
          stroke="currentColor"
          strokeDasharray="14 42"
          strokeLinecap="round"
          strokeWidth="2.25"
        />
      </svg>
    </span>
  )
}

const trailingMotionTransition = (reduceMotion: boolean) => ({
  duration: reduceMotion ? 0 : TRAILING_ACTION_DURATION_SEC,
  ease: "easeOut" as const,
})

const trailingCrossfade = (reduceMotion: boolean) => ({
  exit: {
    opacity: reduceMotion ? 1 : 0,
    scale: reduceMotion ? 1 : 0.25,
    filter: reduceMotion ? "none" : "blur(4px)",
  },
  initial: {
    opacity: reduceMotion ? 1 : 0,
    scale: reduceMotion ? 1 : 0.25,
    filter: reduceMotion ? "none" : "blur(4px)",
  },
})

const trailingEnter = (reduceMotion: boolean) => ({
  opacity: 1,
  scale: 1,
  filter: reduceMotion ? "none" : "blur(0px)",
})

/** Raised “thumb” surface — radius = trigger inner (~10px) − inset so corners don’t crowd the rim */
const trailingThumbSurface = cn(
  "rounded-[6px] bg-background",
  "shadow-[0_1px_0_rgba(255,255,255,0.85)_inset,0_1px_2px_rgba(0,0,0,0.07),0_2px_10px_rgba(0,0,0,0.05)]",
  "ring-1 ring-black/8 dark:ring-white/12",
  "dark:shadow-[0_1px_0_rgba(255,255,255,0.12)_inset,0_1px_3px_rgba(0,0,0,0.45),0_2px_12px_rgba(0,0,0,0.35)]",
  "fine-hover:group-hover/select:ring-2 fine-hover:group-hover/select:ring-ring/20"
)

function resolveTrailingMode(
  isLoading: boolean,
  selectionFlash: boolean,
  showSelectionFlash: boolean,
  reduceMotion: boolean
): "spinner" | "check" | "chevron" {
  if (isLoading) {
    return "spinner"
  }
  if (selectionFlash && showSelectionFlash && !reduceMotion) {
    return "check"
  }
  return "chevron"
}

/** Inset 1px inside `rounded-xl` shell → inner radius 12px − 1px = 11px (concentric with trigger). */
function SelectGradientUnderlay({
  borderGlow,
  translucent,
  reduceMotion,
}: {
  borderGlow: BorderGlowConfig
  translucent: boolean
  reduceMotion: boolean
}) {
  return (
    <div className="pointer-events-none absolute inset-0 overflow-hidden rounded-[11px]">
      {translucent ? (
        <div
          className={cn(
            "absolute inset-0",
            reduceMotion ? "opacity-[0.38]" : "opacity-50"
          )}
        >
          <div
            className="absolute inset-0 blur-2xl"
            style={{
              background:
                "radial-gradient(90% 70% at 50% 100%, rgba(255,0,128,0.28), rgba(121,40,202,0.12) 48%, transparent 62%)",
            }}
          />
          <div
            className="absolute inset-0 opacity-70 blur-xl dark:opacity-50"
            style={{
              background:
                "radial-gradient(70% 55% at 30% 0%, rgba(0,212,255,0.22), rgba(0,112,243,0.08) 45%, transparent 58%)",
            }}
          />
        </div>
      ) : null}
      <motion.div
        animate={{
          opacity: borderGlow.opacityIdle * (translucent ? 0.72 : 1),
        }}
        className="absolute inset-x-0 bottom-0 h-1/2"
        transition={{ duration: 0.25, ease: "easeOut" }}
      >
        <motion.div
          animate={{
            left: borderGlow.primaryLeft,
          }}
          className="-bottom-4 absolute h-16 w-48 blur-xl"
          style={{
            background: borderGlow.primaryBg,
          }}
          transition={{
            duration: borderGlow.durationMain,
            repeat: Number.POSITIVE_INFINITY,
            ease: "easeInOut",
          }}
        />
        <motion.div
          animate={{
            left: borderGlow.secondaryLeft,
          }}
          className="-bottom-3 absolute h-12 w-32 blur-lg"
          style={{
            background: borderGlow.secondaryBg,
          }}
          transition={{
            duration: borderGlow.durationSec,
            repeat: Number.POSITIVE_INFINITY,
            ease: "easeInOut",
          }}
        />
        <motion.div
          animate={{
            left: borderGlow.tertiaryLeft,
          }}
          className="-bottom-2 absolute h-10 w-24 blur-lg"
          style={{
            background: borderGlow.tertiaryBg,
          }}
          transition={{
            duration: borderGlow.durationTer,
            repeat: Number.POSITIVE_INFINITY,
            ease: "easeInOut",
          }}
        />
      </motion.div>
    </div>
  )
}

export type HaloSelectProps = Omit<
  ComponentProps<typeof Select>,
  "children" | "onValueChange"
> & {
  children: ReactNode
  /** Frosted glass style on the trigger track */
  translucent?: boolean
  isLoading?: boolean
  showSelectionFlash?: boolean
  /** Shown when no value is selected; also forwarded to `HaloSelectValue` via context */
  placeholder?: string
  className?: string
  onValueChange?: (
    value: unknown,
    eventDetails: SelectValueChangeDetails
  ) => void
}

function staggerDurationMs(text: string, reduceMotion: boolean): number {
  if (reduceMotion || text.length === 0) {
    return 0
  }
  const n = text.length
  const runSec = (n - 1) * LABEL_STAGGER_SEC + LABEL_CHAR_DURATION_SEC
  return runSec * 1000 + 80
}

/**
 * Root: Base UI `Select` plus internal context for stagger, rim, and trailing indicator.
 * Compose with `HaloSelectTrigger`, `HaloSelectContent`, and items — same idea as
 * [`Select`](components/ui/select.tsx) + `SelectTrigger` + `SelectContent`.
 */
export function HaloSelect({
  children,
  translucent = false,
  isLoading = false,
  showSelectionFlash = true,
  placeholder = "Select an option",
  className,
  value: valueProp,
  defaultValue,
  onValueChange,
  onOpenChange: onOpenChangeUser,
  ...selectProps
}: HaloSelectProps) {
  const reduceMotion = useReducedMotion() ?? false
  const generatedId = useId()
  const fieldId = selectProps.id ?? generatedId
  const [open, setOpen] = useState(false)
  const [isFocused, setIsFocused] = useState(false)
  const [listBurst, setListBurst] = useState(0)
  const [labelStagger, setLabelStagger] = useState({ key: 0, text: "" })
  const [isStaggering, setIsStaggering] = useState(false)
  const [selectionFlash, setSelectionFlash] = useState(false)
  const flashTimerRef = useRef<number | null>(null)

  const isControlled = valueProp !== undefined
  const isActive = isFocused || open
  const showBlobTranslucent = translucent

  const borderGlow = useMemo((): BorderGlowConfig => {
    let idleOpacity: number
    if (showBlobTranslucent) {
      idleOpacity = isActive ? 0.92 : 0.76
    } else {
      idleOpacity = isActive ? 0.82 : 0.58
    }
    return {
      opacityIdle: idleOpacity,
      primaryBg: "linear-gradient(90deg, #ff0080, #7928ca, #00d4ff, #0070f3)",
      secondaryBg: "linear-gradient(90deg, #ff4d4d, #f9cb28, #ff0080)",
      tertiaryBg: "linear-gradient(90deg, #0070f3, #00d4ff, #7928ca)",
      primaryLeft: ["-5%", "75%", "-5%"],
      secondaryLeft: ["65%", "10%", "65%"],
      tertiaryLeft: ["25%", "55%", "25%"],
      durationMain: 6,
      durationSec: 5,
      durationTer: 4,
    }
  }, [showBlobTranslucent, isActive])

  useEffect(() => {
    if (open) {
      setListBurst((b) => b + 1)
    }
  }, [open])

  useEffect(() => {
    return () => {
      if (flashTimerRef.current) {
        window.clearTimeout(flashTimerRef.current)
      }
    }
  }, [])

  useEffect(() => {
    const text = labelStagger.text
    if (reduceMotion || !text || open) {
      setIsStaggering(false)
      return
    }
    setIsStaggering(true)
    const ms = staggerDurationMs(text, reduceMotion)
    const t = window.setTimeout(() => setIsStaggering(false), ms)
    return () => window.clearTimeout(t)
  }, [labelStagger, open, reduceMotion])

  const handleValueChange = useCallback(
    (next: unknown, eventDetails: SelectValueChangeDetails) => {
      onValueChange?.(next, eventDetails)
      if (
        next &&
        typeof next === "object" &&
        "label" in next &&
        typeof (next as PolishedSelectItem).label === "string"
      ) {
        setLabelStagger((s) => ({
          key: s.key + 1,
          text: (next as PolishedSelectItem).label,
        }))
        if (showSelectionFlash && !reduceMotion) {
          if (flashTimerRef.current) {
            window.clearTimeout(flashTimerRef.current)
          }
          setSelectionFlash(true)
          flashTimerRef.current = window.setTimeout(() => {
            setSelectionFlash(false)
            flashTimerRef.current = null
          }, SELECTION_FLASH_MS)
        }
      } else {
        setLabelStagger({ key: 0, text: "" })
      }
    },
    [onValueChange, reduceMotion, showSelectionFlash]
  )

  const showStaggerOverlay =
    Boolean(labelStagger.text) && isStaggering && !open && !reduceMotion

  const trailingMode = resolveTrailingMode(
    isLoading,
    selectionFlash,
    showSelectionFlash,
    reduceMotion
  )

  const contextValue = useMemo(
    (): HaloSelectContextValue => ({
      translucent: showBlobTranslucent,
      isLoading,
      showSelectionFlash,
      reduceMotion,
      open,
      setOpen,
      isFocused,
      setIsFocused,
      listBurst,
      labelStagger,
      showStaggerOverlay,
      placeholder,
      borderGlow,
      trailingMode,
      fieldId,
    }),
    [
      showBlobTranslucent,
      isLoading,
      showSelectionFlash,
      reduceMotion,
      open,
      isFocused,
      listBurst,
      labelStagger,
      showStaggerOverlay,
      placeholder,
      borderGlow,
      trailingMode,
      fieldId,
    ]
  )

  return (
    <HaloSelectContext.Provider value={contextValue}>
      <div
        className={cn(
          "relative inline-block w-max min-w-0 max-w-full",
          className
        )}
      >
        <Select
          {...selectProps}
          defaultValue={
            isControlled
              ? undefined
              : (defaultValue as PolishedSelectItem | undefined)
          }
          disabled={selectProps.disabled || isLoading}
          onOpenChange={(nextOpen, eventDetails) => {
            setOpen(nextOpen)
            onOpenChangeUser?.(nextOpen, eventDetails)
          }}
          onValueChange={handleValueChange}
          open={open}
          value={isControlled ? (valueProp ?? null) : undefined}
        >
          {children}
        </Select>
      </div>
    </HaloSelectContext.Provider>
  )
}

export type HaloSelectTriggerProps = SelectPrimitive.Trigger.Props

/**
 * Gradient rim + pill trigger shell. Place `HaloSelectValue` and
 * `HaloSelectTrailingIndicator` inside (same role as `SelectTrigger` + value + icon).
 */
export function HaloSelectTrigger({
  className,
  children,
  onBlur,
  onFocus,
  ...props
}: HaloSelectTriggerProps) {
  const {
    translucent,
    isLoading,
    open,
    reduceMotion,
    isFocused,
    setIsFocused,
    borderGlow,
    fieldId,
  } = useHaloSelect()

  const ringActive = isFocused || open

  return (
    <div className="relative w-fit max-w-full rounded-xl p-px">
      <SelectGradientUnderlay
        borderGlow={borderGlow}
        reduceMotion={reduceMotion}
        translucent={translucent}
      />
      <SelectPrimitive.Trigger
        aria-busy={isLoading || props["aria-busy"]}
        className={cn(
          "relative inline-flex min-h-11 min-w-34 max-w-[min(100%,20rem)] items-center gap-2 rounded-[11px] py-2 pr-2 pl-3 text-left",
          "whitespace-nowrap antialiased",
          "border border-[color-mix(in_oklch,var(--border)_72%,oklch(0.88_0.06_300))] bg-transparent",
          /* Shell stack: top inset highlight + contact shadow + soft lift — aligned with HaloSwitch / HaloBadge */
          "shadow-[0_1px_0_rgba(255,255,255,0.55)_inset,0_1px_2px_rgba(0,0,0,0.03),0_6px_18px_rgba(0,0,0,0.04)]",
          "dark:border-border/80 dark:shadow-[0_1px_0_rgba(255,255,255,0.05)_inset,0_1px_2px_rgba(0,0,0,0.28),0_6px_22px_rgba(0,0,0,0.32)]",
          "group/select outline-none transition-[background-color,backdrop-filter,border-color,box-shadow] duration-200 ease-out",
          "fine-hover:hover:border-ring/50 fine-hover:hover:shadow-[0_1px_0_rgba(255,255,255,0.6)_inset,0_1px_3px_rgba(0,0,0,0.05),0_8px_22px_rgba(0,0,0,0.06)]",
          "dark:fine-hover:hover:border-zinc-500/60 dark:fine-hover:hover:shadow-[0_1px_0_rgba(255,255,255,0.08)_inset,0_2px_4px_rgba(0,0,0,0.38),0_10px_28px_rgba(0,0,0,0.42)]",
          "focus-visible:border-ring/80 focus-visible:ring-2 focus-visible:ring-ring/30",
          "disabled:cursor-not-allowed disabled:opacity-50",
          "data-placeholder:text-muted-foreground",
          ringActive &&
            "border-ring/70 shadow-[0_1px_0_rgba(255,255,255,0.14)_inset,0_1px_2px_rgba(0,0,0,0.09),0_4px_14px_rgba(0,0,0,0.11)] dark:border-zinc-500/55 dark:shadow-[0_1px_0_rgba(255,255,255,0.08)_inset,0_1px_2px_rgba(0,0,0,0.42),0_4px_20px_rgba(0,0,0,0.48)]",
          translucent && "backdrop-blur-xl backdrop-saturate-150",
          className
        )}
        data-slot="halo-select-trigger"
        disabled={props.disabled ?? isLoading}
        id={props.id ?? fieldId}
        onBlur={(e) => {
          setIsFocused(false)
          onBlur?.(e)
        }}
        onFocus={(e) => {
          setIsFocused(true)
          onFocus?.(e)
        }}
        style={{
          background: translucent
            ? "linear-gradient(to bottom, color-mix(in oklch, var(--card) 82%, oklch(0.92 0.04 330)) 0%, color-mix(in oklch, var(--card) 78%, oklch(0.88 0.06 285)) 50%, color-mix(in oklch, var(--card) 76%, oklch(0.9 0.05 245)) 100%)"
            : "linear-gradient(to bottom, color-mix(in oklch, var(--card) 95%, oklch(0.97 0.02 315)) 0%, color-mix(in oklch, var(--card) 93%, oklch(0.96 0.025 280)) 100%)",
          ...props.style,
        }}
        {...props}
        type="button"
      >
        {children}
      </SelectPrimitive.Trigger>
    </div>
  )
}

export function HaloSelectValue({
  className,
  placeholder: placeholderProp,
  ...props
}: SelectPrimitive.Value.Props) {
  const {
    placeholder: contextPlaceholder,
    showStaggerOverlay,
    labelStagger,
    reduceMotion,
  } = useHaloSelect()

  return (
    <div className="relative min-w-0 flex-1 text-sm/relaxed">
      <SelectPrimitive.Value
        className={cn(
          "block min-w-0 flex-1 truncate bg-transparent text-foreground text-sm/relaxed",
          showStaggerOverlay && "text-transparent",
          className
        )}
        data-slot="halo-select-value"
        placeholder={placeholderProp ?? contextPlaceholder}
        {...props}
      />
      {showStaggerOverlay && (
        <SelectStaggeredGlyphLine
          animateKey={labelStagger.key}
          className="pointer-events-none absolute inset-y-0 left-0 flex items-center text-foreground"
          reduceMotion={reduceMotion}
          text={labelStagger.text}
        />
      )}
    </div>
  )
}

/** Chevron / check / spinner aligned with the trigger (like `SelectPrimitive.Icon` usage). */
export function HaloSelectTrailingIndicator({
  className,
}: {
  className?: string
}) {
  const { trailingMode, reduceMotion, open } = useHaloSelect()
  const cross = trailingCrossfade(reduceMotion)
  const transition = trailingMotionTransition(reduceMotion)

  return (
    <div className={cn("relative size-8 shrink-0", className)}>
      {/*
        Thumb shell stays static; only the glyph crossfades (enter/exit). `initial` must
        not be false on animated children so the first paint is not stuck invisible.
      */}
      <div
        aria-hidden
        className={cn(
          "pointer-events-none absolute inset-0 flex items-center justify-center",
          trailingThumbSurface
        )}
      />
      <div className="absolute inset-0 flex items-center justify-center">
        <AnimatePresence mode="sync">
          {trailingMode === "spinner" && (
            <motion.span
              animate={trailingEnter(reduceMotion)}
              aria-hidden
              className="absolute inset-0 flex items-center justify-center text-muted-foreground"
              exit={cross.exit}
              initial={cross.initial}
              key="trail-spin"
              transition={transition}
            >
              <TrailingSpinner reduceMotion={reduceMotion} />
            </motion.span>
          )}
          {trailingMode === "check" && (
            <motion.span
              animate={trailingEnter(reduceMotion)}
              aria-hidden
              className="absolute inset-0 flex items-center justify-center text-emerald-600 dark:text-emerald-400"
              exit={cross.exit}
              initial={cross.initial}
              key="trail-check"
              transition={transition}
            >
              <Check className="h-3.5 w-3.5" strokeWidth={2.5} />
            </motion.span>
          )}
          {trailingMode === "chevron" && (
            <motion.span
              animate={trailingEnter(reduceMotion)}
              aria-hidden
              className="absolute inset-0 flex items-center justify-center text-muted-foreground"
              exit={cross.exit}
              initial={cross.initial}
              key="trail-chevron"
              transition={transition}
            >
              <motion.span
                animate={{
                  rotate: !reduceMotion && open ? 180 : 0,
                }}
                className="inline-flex"
                transition={transition}
              >
                <ChevronDown className="h-3.5 w-3.5" />
              </motion.span>
            </motion.span>
          )}
        </AnimatePresence>
      </div>
    </div>
  )
}

