export type PollWidgetOptionsProps = HTMLAttributes<HTMLDivElement>

/**
 * Container for poll options with keyboard navigation.
 */
export function PollWidgetOptions({
  className,
  children,
  ...props
}: PollWidgetOptionsProps) {
  const containerRef = useRef<HTMLDivElement>(null)

  const handleKeyDown = useCallback((event: KeyboardEvent<HTMLDivElement>) => {
    const container = containerRef.current
    if (!container) {
      return
    }

    const options = Array.from(
      container.querySelectorAll<HTMLButtonElement>(
        '[data-slot="poll-widget-option"]:not([disabled])'
      )
    )
    const currentIndex = options.indexOf(
      document.activeElement as HTMLButtonElement
    )

    let nextIndex = currentIndex

    switch (event.key) {
      case "ArrowDown":
      case "ArrowRight":
        event.preventDefault()
        nextIndex = currentIndex < options.length - 1 ? currentIndex + 1 : 0
        break
      case "ArrowUp":
      case "ArrowLeft":
        event.preventDefault()
        nextIndex = currentIndex > 0 ? currentIndex - 1 : options.length - 1
        break
      case "Home":
        event.preventDefault()
        nextIndex = 0
        break
      case "End":
        event.preventDefault()
        nextIndex = options.length - 1
        break
      default:
        break
    }

    options[nextIndex]?.focus()
  }, [])

  return (
    <div
      className={cn("flex flex-col gap-2", className)}
      data-slot="poll-widget-options"
      onKeyDown={handleKeyDown}
      ref={containerRef}
      role="listbox"
      {...props}
    >
      {children}
    </div>
  )
}

// ============================================================================
// Option Component
// ============================================================================

export type PollWidgetOptionProps = Omit<ComponentProps<"button">, "value"> & {
  /** Unique identifier for this option */
  value: string
  /** Whether this specific option is disabled */
  disabled?: boolean
}

/**
 * Individual poll option with indicator, label, and progress bar.
 */
export function PollWidgetOption({
  value,
  disabled: optionDisabled = false,
  children,
  className,
  onClick,
  ...props
}: PollWidgetOptionProps) {
  const {
    options,
    disabled: rootDisabled,
    hasVoted,
    showResults,
    isSelected,
    select,
    getPercentage,
  } = usePollWidget()

  const option = options.find((o) => o.id === value)
  const disabled = rootDisabled || optionDisabled
  const selected = isSelected(value)
  const percentage = getPercentage(value)

  const getState = (): "idle" | "selected" | "voted" => {
    if (hasVoted) {
      return "voted"
    }
    if (selected) {
      return "selected"
    }
    return "idle"
  }
  const state = getState()

  const handleClick = useCallback(
    (event: MouseEvent<HTMLButtonElement>) => {
      onClick?.(event)
      if (!(event.defaultPrevented || disabled)) {
        select(value)
      }
    },
    [onClick, disabled, select, value]
  )

  const optionContextValue = useMemo(
    () => ({
      optionId: value,
      disabled,
      isSelected: selected,
      percentage,
    }),
    [value, disabled, selected, percentage]
  )

  return (
    <PollWidgetOptionContext.Provider value={optionContextValue}>
      <button
        aria-disabled={disabled || hasVoted}
        aria-selected={selected}
        className={cn(optionVariants({ state }), className)}
        data-disabled={disabled ? true : undefined}
        data-percentage={percentage}
        data-selected={selected ? true : undefined}
        data-slot="poll-widget-option"
        data-state={state}
        data-value={value}
        disabled={disabled || hasVoted}
        onClick={handleClick}
        role="option"
        type="button"
        {...props}
      >
        {/* Animated progress bar background */}
        {showResults && (
          <motion.span
            animate={{ width: `${percentage}%` }}
            aria-hidden="true"
            className={cn(
              progressVariants({ state: selected ? "selected" : "voted" })
            )}
            initial={{ width: 0 }}
            transition={{
              type: "spring",
              duration: 0.8,
              bounce: 0.1,
              delay: 0.1,
            }}
          />
        )}

        {/* Content */}
        <span className="relative z-10 flex w-full items-center gap-3">
          {children ?? (
            <>
              <PollWidgetIndicator />
              {option?.icon && (
                <span className="text-muted-foreground shrink-0">
                  {option.icon}
                </span>
              )}
              <PollWidgetLabel>
                {option?.label ?? value}
                {option?.description && (
                  <span className="text-muted-foreground block text-xs font-normal">
                    {option.description}
                  </span>
                )}
              </PollWidgetLabel>
              {showResults && <PollWidgetPercentage />}
            </>
          )}
        </span>
      </button>
    </PollWidgetOptionContext.Provider>
  )
}

